class Solution {
    function convert($s, $numRows) {
        if ($numRows === 1 || $numRows >= strlen($s)) return $s;
        $rows = array_fill(0, $numRows, "");
        $row = 0; $dir = -1; $n = strlen($s);
        for ($i = 0; $i < $n; $i++) {
            if ($row === 0 || $row === $numRows - 1) $dir = -$dir;
            $rows[$row] .= $s[$i];
            $row += $dir;
        }
        return implode("", $rows);
    }
}

